import { test, expect } from '@playwright/test';

test.describe('Profile Update Confirmation Message', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/profile');
  });

  test('should display confirmation message after successful profile update', async ({ page }) => {
    // Setup: Fill in new profile details using getByLabel
    const firstNameInput = page.getByLabel('First Name');
    await firstNameInput.fill('John');

    const lastNameInput = page.getByLabel('Last Name');
    await lastNameInput.fill('Doe');

    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('john.doe@example.com');

    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('NewPassword123');

    // Verify update button is visible and enabled
    const updateButton = page.getByRole('button', { name: /update profile/i });
    await expect(updateButton).toBeVisible();

    // Click update button
    await updateButton.click();

    // Verify confirmation modal is visible
    const confirmationModal = page.getByRole('dialog');
    await expect(confirmationModal).toBeVisible();

    // Verify confirmation message contains expected text
    const confirmationText = page.getByText(/Your profile has been updated successfully/i);
    await expect(confirmationText).toBeVisible();

    // Verify success message
    const successMessage = page.getByText(/Profile updated successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify user is redirected to profile page
    const profilePage = page.getByRole('main');
    await expect(profilePage).toBeVisible();

    // Verify updated profile details are displayed
    const updatedFirstName = page.getByText('John');
    await expect(updatedFirstName).toBeVisible();

    const updatedLastName = page.getByText('Doe');
    await expect(updatedLastName).toBeVisible();

    const updatedEmail = page.getByText('john.doe@example.com');
    await expect(updatedEmail).toBeVisible();
  });

  test('should not display confirmation message if update fails', async ({ page }) => {
    // Setup: Fill in invalid email using getByLabel
    const firstNameInput = page.getByLabel('First Name');
    await firstNameInput.fill('Jane');

    const lastNameInput = page.getByLabel('Last Name');
    await lastNameInput.fill('Smith');

    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('invalid-email');

    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('SecurePassword123');

    // Verify update button is visible and enabled
    const updateButton = page.getByRole('button', { name: /update profile/i });
    await expect(updateButton).toBeVisible();

    // Click update button
    await updateButton.click();

    // Verify error message is displayed
    const errorMessage = page.getByText(/Email address is invalid/i);
    await expect(errorMessage).toBeVisible();

    // Verify confirmation modal is not visible
    const confirmationModal = page.getByRole('dialog');
    await expect(confirmationModal).not.toBeVisible();

    // Verify user is not redirected
    const profilePage = page.getByRole('main');
    await expect(profilePage).toBeVisible();

    // Verify error message is displayed
    const errorText = page.getByText(/Email address is invalid/i);
    await expect(errorText).toBeVisible();
  });
});
